'use strict';
const reportStages=['Стратегия и подбор университетов','Подготовка документов','Подача заявок','Интервью','Результаты и выбор оффера','Виза и подготовка к отъезду','Другой этап'];
let selectedReportId=null;
function reportDateValid(value){return typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value}
function reportDraft(c){const end=iso(today);return {stage:reportStages[0],from:c.startDate&&c.startDate<=end?c.startDate:end,to:end,done:'',next:'',clientAction:'',appIds:c.apps.slice(0,6).map(a=>a.id)}}
function buildReport(c,data){
 if(!reportStages.includes(data.stage))throw new Error('Выберите этап отчёта.');
 if(!reportDateValid(data.from)||!reportDateValid(data.to)||data.from>data.to||data.to>iso(today))throw new Error('Проверьте период: начало не позже окончания, окончание не позже сегодня.');
 for(const [key,max,label] of [['done',500,'Итоги этапа'],['next',400,'Следующий этап'],['clientAction',300,'Что нужно от клиента']]){if(typeof data[key]!=='string'||!data[key].trim()||data[key].length>max)throw new Error(`${label}: заполните поле, не более ${max} символов.`)}
 const selected=c.apps.filter(a=>data.appIds.includes(a.id));if(selected.length>8)throw new Error('Выберите не более 8 заявок для одностраничного отчёта. Остальные будут учтены в общей сводке.');
 const copy=JSON.parse(JSON.stringify({demo:!!c.demo,client:{name:c.name,level:c.level,year:c.year,semester:c.semester||'',consultant:c.consultant||''},stage:data.stage,from:data.from,to:data.to,done:data.done.trim(),next:data.next.trim(),clientAction:data.clientAction.trim(),applications:selected.map(a=>({university:a.university,program:a.program,status:a.status,deadline:a.deadline,feeAmount:a.feeAmount??null,feeCurrency:a.feeCurrency||'USD',feeStatus:a.feeStatus||'unknown'})),appCount:c.apps.length,sentCount:completed(c),offerCount:c.apps.filter(a=>a.status==='Оффер').length,fees:feeTotals(c.apps),periodFees:feeTotals(c.apps.filter(a=>a.feePaidDate&&a.feePaidDate>=data.from&&a.feePaidDate<=data.to)),undatedPaid:c.apps.filter(a=>a.feeStatus==='paid'&&!a.feePaidDate).length}));
 return {id:crypto.randomUUID(),...copy,createdAt:new Date().toISOString(),createdDate:iso(new Date()),sent:null,ack:null};
}
function selectedReport(c){return (c.reports||[]).find(r=>r.id===selectedReportId)||(c.reports||[])[0]}
function reportStatus(r){return r.ack?'Ознакомление подтверждено':r.sent?'Отправлен · ждём ответа':'Подготовлен'}
function reportPaper(r){const periodFees=r.periodFees.map(t=>money(t.amount,t.currency)).join(' + ')||'Нет оплат с датой в этом периоде';const allFees=r.fees.map(t=>money(t.amount,t.currency)).join(' + ')||'Оплаченные сборы не внесены';return `<article class="report-paper" id="report-paper"><div class="report-inner"><header class="report-header"><strong>GrantEd<span>Сопровождение поступления</span></strong><div>${r.demo?'ДЕМОНСТРАЦИОННЫЙ ОТЧЁТ':'ОТЧЁТ ПО ЭТАПУ'}<br><span>${fullDate((r.createdDate||r.createdAt.slice(0,10)))}</span></div></header><h1>${esc(r.client.name)}</h1><div class="report-subtitle">${esc(r.client.level)} · ${esc(r.client.semester&&r.client.semester!=='Не указан'?r.client.semester+' ':'')}${r.client.year}</div><div class="report-stage"><h2>${esc(r.stage)}</h2><p>Период: ${fullDate(r.from)} — ${fullDate(r.to)}</p></div><section class="report-section"><h2>01 / Итоги этапа</h2><p>${esc(r.done)}</p></section><section class="report-section"><h2>02 / Заявки в университеты</h2><p class="report-caption">На ${fullDate((r.createdDate||r.createdAt.slice(0,10)))}: Заявок: ${r.appCount} · отправлено: ${r.sentCount} · офферов: ${r.offerCount}</p>${r.applications.length?`<table class="report-table"><thead><tr><th>Университет / программа</th><th>Статус</th><th>Дедлайн</th><th>Application fee</th></tr></thead><tbody>${r.applications.map(a=>`<tr><td>${esc(a.university)}<small>${esc(a.program)}</small></td><td>${esc(a.status)}</td><td>${fmt(a.deadline)}</td><td>${a.feeStatus==='paid'?money(a.feeAmount,a.feeCurrency):a.feeStatus==='waived'?'Waiver / без сбора':a.feeAmount!==null?money(a.feeAmount,a.feeCurrency):'Не указан'}<small>${esc(feeLabels[a.feeStatus]||'Не указан')}</small></td></tr>`).join('')}</tbody></table>`:'<p class="report-caption">Подробные заявки в этот отчёт не включены.</p>'}${r.appCount>r.applications.length?`<p class="report-caption">Показано ${r.applications.length} из ${r.appCount} заявок. Общая сводка и расходы учитывают все заявки.</p>`:''}</section><section class="report-section report-fees"><h2>03 / Расходы клиента на application fee</h2><p><b>За период:</b> ${periodFees}<br><b>Всего на дату отчёта:</b> ${allFees}</p>${r.undatedPaid?`<p class="report-caption">${r.undatedPaid} оплат без даты учтены только в общем итоге.</p>`:''}</section><section class="report-section"><h2>04 / Следующий этап</h2><p>${esc(r.next)}</p></section><section class="report-action"><h2>Что нужно от вас</h2><p>${esc(r.clientAction)}</p></section><footer class="report-footer"><span>Консультант: ${esc(r.client.consultant||'не указан')}</span><span>Пожалуйста, подтвердите ознакомление ответным сообщением.</span></footer></div></article>`}
function renderReports(c){const r=selectedReport(c);return `<div class="section-top"><div><h2>Отчёты для клиента</h2><p class="subtle">По завершении этапа · 1 страница A4</p></div><button class="primary" data-report-action="create" data-client="${c.id}">${icon('plus')} Создать отчёт</button></div><div class="notice">Сформируйте PDF и отправьте клиенту удобным способом. Отправка и ознакомление отмечаются вручную после фактического действия; автоматической рассылки нет.</div>${r?`<div class="report-history">${(c.reports||[]).map(item=>`<button data-report-action="select" data-client="${c.id}" data-report="${item.id}" class="${r.id===item.id?'selected':''}"><strong>${esc(item.stage)}</strong><span>${fullDate((item.createdDate||item.createdAt.slice(0,10)))} · ${reportStatus(item)}</span></button>`).join('')}</div><div class="report-toolbar"><span class="badge ${r.ack?'green':r.sent?'blue':''}">${reportStatus(r)}</span><div class="btnrow"><button class="primary" data-report-action="download" data-client="${c.id}">Скачать PDF</button><button data-report-action="print" data-client="${c.id}">Печать</button>${!r.sent?`<button data-report-action="sent" data-client="${c.id}" data-report="${r.id}">Отметить отправку</button>`:!r.ack?`<button data-report-action="ack" data-client="${c.id}" data-report="${r.id}">Подтвердить ознакомление</button>`:''}</div></div>${r.sent?`<p class="subtle">Отправка: ${fullDate(r.sent.date)} · ${esc(r.sent.channel)} · отмечено администратором.</p>`:''}${r.ack?`<p class="subtle">Ознакомление: ${fullDate(r.ack.date)} · ${esc(r.ack.channel)} · ${esc(r.ack.note)}. Внесено администратором по ответу клиента.</p>`:''}<p id="report-download" class="subtle" role="status"></p><p id="report-fit-error" class="error" role="alert"></p><div class="report-preview">${reportPaper(r)}</div><p class="local-note">Снимок на момент формирования. Внутренние заметки и контактные данные не включены. История хранится только в этом браузере.</p>`:'<div class="empty"><h3>Первый отчёт по завершении этапа</h3>В отчёте будут итоги, статусы заявок, расходы и следующие шаги.<br>Сначала внесите итоги этапа — CRM не определяет их автоматически.</div>'}`}
function newReportForm(c){const draft=reportDraft(c);showModal('Отчёт по завершении этапа',`<form id="report-form" data-client="${c.id}"><label>Завершённый этап<select name="stage">${options(reportStages,draft.stage)}</select></label><div class="row"><label>Начало периода<input name="from" type="date" required max="${iso(today)}" value="${draft.from}"></label><label>Конец периода<input name="to" type="date" required max="${iso(today)}" value="${draft.to}"></label></div><label>Итоги этапа · до 500 символов<textarea name="done" rows="4" required maxlength="500" placeholder="Какая работа выполнена и какого результата достигли…"></textarea></label><label>Следующий этап · до 400 символов<textarea name="next" rows="3" required maxlength="400" placeholder="Что будет сделано дальше и в какие сроки…"></textarea></label><label>Что нужно от клиента · до 300 символов<textarea name="clientAction" rows="3" required maxlength="300" placeholder="Действия клиента и сроки, либо «Дополнительных действий не требуется»…"></textarea></label><fieldset class="report-pick"><legend>Заявки в отчёте · до 8</legend><p class="subtle">Сводка и расходы учтут все заявки. Выберите те, которые важно показать подробно.</p>${c.apps.map(a=>`<label><input type="checkbox" name="application" value="${a.id}" ${draft.appIds.includes(a.id)?'checked':''}>${esc(a.university)} · ${esc(a.program)}</label>`).join('')||'<p class="subtle">Заявок пока нет.</p>'}</fieldset><p class="subtle">В отчёт попадут текущие статусы, а не исторические статусы за прошлый период. Перед отправкой проверьте PDF.</p>${footer('Сформировать отчёт')}</form>`)}
function recordReportEvent(c,reportId,kind,data){const report=(c.reports||[]).find(r=>r.id===reportId);if(!report)throw new Error('Отчёт не найден.');if(!['sent','ack'].includes(kind))throw new Error('Неизвестное действие.');if(kind==='ack'&&!report.sent)throw new Error('Сначала отметьте фактическую отправку.');if(report[kind])throw new Error('Это действие уже отмечено.');const minDate=kind==='ack'?report.sent.date:(report.createdDate||report.createdAt.slice(0,10));if(!reportDateValid(data.date)||data.date<minDate||data.date>iso(today))throw new Error('Дата должна быть не раньше предыдущего действия и не позже сегодня.');if(!['WhatsApp','Email','Личная встреча','Звонок','Другой канал'].includes(data.channel))throw new Error('Выберите канал.');if(kind==='ack'&&!data.note?.trim())throw new Error('Укажите, как клиент подтвердил ознакомление.');const value={date:data.date,channel:data.channel,note:(data.note||'').trim(),recordedAt:new Date().toISOString(),source:'admin_manual'};report[kind]=value;return value}
function reportEventForm(c,r,kind){showModal(kind==='sent'?'Отметить фактическую отправку':'Подтвердить ознакомление',`<form id="report-event-form" data-client="${c.id}" data-report="${r.id}" data-kind="${kind}"><p>${kind==='sent'?'Отметьте только уже отправленный клиенту отчёт. Эта кнопка не отправляет сообщения.':'Внесите подтверждение, которое вы уже получили от клиента. Открытие PDF само по себе не означает ознакомления.'}</p><label>Дата<input type="date" name="date" required min="${kind==='ack'?r.sent.date:(r.createdDate||r.createdAt.slice(0,10))}" max="${iso(today)}" value="${iso(today)}"></label><label>Канал<select name="channel">${options(['WhatsApp','Email','Личная встреча','Звонок','Другой канал'])}</select></label>${kind==='ack'?'<label>Подтверждение клиента<textarea name="note" required maxlength="250" rows="3" placeholder="Например: ответил «Ознакомился, всё понятно» в WhatsApp"></textarea></label>':''}${footer(kind==='sent'?'Отправка состоялась':'Подтверждение получено')}</form>`)}
function printReport(){const paper=$('#report-paper');if(!paper)return;const inner=paper.querySelector('.report-inner');const maxHeight=1000;inner.style.fontSize='';if(inner.scrollHeight>maxHeight){$('#report-fit-error').textContent='Отчёт не помещается на одну страницу. Сформируйте новый с более коротким текстом или меньшим количеством подробных заявок.';return}$('#report-fit-error').textContent='';const root=document.createElement('div');root.id='report-print-root';root.innerHTML=paper.outerHTML;document.body.append(root);document.body.classList.add('printing-report');const cleanup=()=>{document.body.classList.remove('printing-report');root.remove();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);window.print();}
function initReports(){
 document.addEventListener('click',e=>{const b=e.target.closest('[data-report-action]');if(!b)return;const c=clientById(b.dataset.client);if(!c)return;const r=(c.reports||[]).find(x=>x.id===b.dataset.report);switch(b.dataset.reportAction){case'create':newReportForm(c);break;case'select':selectedReportId=r?.id;render();break;case'print':printReport();break;case'download':downloadReportPdf(c,b);break;case'sent':case'ack':if(r)reportEventForm(c,r,b.dataset.reportAction);break}});
 document.addEventListener('submit',async e=>{const f=e.target;if(!['report-form','report-event-form'].includes(f.id))return;e.preventDefault();const c=clientById(f.dataset.client);const fields=new FormData(f);const data=Object.fromEntries(fields);try{if(f.id==='report-form'){data.appIds=fields.getAll('application');const report=buildReport(c,data);c.reports=c.reports||[];c.reports.unshift(report);if(!await save()){c.reports.shift();return}selectedReportId=report.id;}else{recordReportEvent(c,f.dataset.report,f.dataset.kind,data);if(!await save()){const r=c.reports.find(r=>r.id===f.dataset.report);r[f.dataset.kind]=null;return}}$('#modal').close();render();toast('Сохранено в истории отчётов');}catch(error){$('#form-error').textContent=error.message}});
}
